for gid, name, skill, desc, fxn in NEW:
    if not os.path.exists(f'v5/{gid}.json'): continue   # not cut yet
    if not REL.get(gid, {}).get('atk', {}).get('wf'): print('SKIPPED (no release point in rel.json):', gid); continue   # her fight would be empty
    lj = f'live_{gid}.json'
    GODS.append({'id': gid, 'name': name, 'skill': skill, 'desc': desc, 'fx': gid, 'live': json.load(open(lj)) if os.path.exists(lj) else None, 'fxNote': fxn,
                 'sheets': {s: (f'v5/{gid}.json', s) for s in ('idle', 'app', 'atk')}, 'files': {s: f'v5/{gid}-bt-{s}.webp' for s in ('idle', 'app', 'atk')}})
ACCEPTED = {'order', 'plague', 'fate', 'life'}   # Maxim 27.11 01:29 «все круто получилось»
out = []
os.makedirs(f'{REPO}/assets/hg/new', exist_ok=True)
for G in GODS:
    nu = {}
    for slot, (mf, key) in G['sheets'].items():
        m = json.load(open(mf))[key]
        srcf = G['files'].get(slot, m['file'])
        dst = f'assets/hg/new/{G["id"]}-bt-{slot}.webp'; shutil.copy(srcf, f'{REPO}/{dst}')
        nu[slot] = {'src': f'{dst}?v={V["v"]}', 'cols': 5, 'rows': 5, 'n': 25, 'fw': m['fw'], 'fh': m['fh'], 'dur': 3.0, 'fig': m['fig'], 'kb': round(os.path.getsize(srcf) / 1024)}
        if slot in REL.get(G['id'], {}): nu[slot].update(REL[G['id']][slot])
    G = {k: v for k, v in G.items() if k not in ('sheets', 'files')}
    G.update(nu=nu, notes=NOTES.get(G['id'], []), accepted=G['id'] in ACCEPTED); out.append(G)
for G in out:   # live sheets: the same version stamp, so a re-cut under the same name reaches the viewers
    for k, L in (G.get('live') or {}).items(): L['src'] = L['src'].split('?')[0] + f'?v={V["v"]}'
js = f'/* generated by hgdata.py: higher goddesses on the review page */\nconst HG_V = {V["v"]};\nconst HG = ' + json.dumps(out, ensure_ascii=False, indent=1) + ';\n'
hp = f'{REPO}/higher.html'; h = open(hp).read(); h2 = re.sub(r'(assets/hg/hg-(?:data|stand)\.js)\?v=\d+', lambda m: f'{m.group(1)}?v={V["v"]}', h)
if h2 != h: open(hp, 'w').write(h2)
open(f'{REPO}/assets/hg/hg-data.js', 'w').write(js); print('hg-data.js', len(js))
